TEE_Result generate_key_for_object(unsigned long obj,
                                   unsigned long key_size,
                                   const struct utee_attribute* usr_params,
                                   unsigned long param_count) {
    TEE_Result result = TEE_SUCCESS;
    void* session = NULL;
    struct key_attributes* attributes = NULL;

    session = TEE_GetCurrentSession();
    if (!session) {
        return TEE_ERROR_BAD_STATE;
    }

    if (key_size < MIN_KEY_SIZE || key_size > MAX_KEY_SIZE) {
        return TEE_ERROR_BAD_PARAMETERS;
    }

    attributes = (struct key_attributes*)malloc(sizeof(struct key_attributes) * (param_count + 1));
    if (!attributes) {
        return TEE_ERROR_OUT_OF_MEMORY;
    }

    for (unsigned long i = 0; i < param_count; i++) {
        attributes[i] = usr_params[i];
    }

    if (obj == TEE_TYPE_AES) {
        result = generate_aes_key(session, key_size, attributes, param_count);
    } else if (obj == TEE_TYPE_RSA) {
        result = generate_rsa_key(session, key_size, attributes, param_count);
    } else if (obj == TEE_TYPE_DSA) {
        result = generate_dsa_key(session, key_size, attributes, param_count);
    } else {
        result = TEE_ERROR_NOT_SUPPORTED;
    }

    if (result != TEE_SUCCESS) {
        free(attributes);
        return result;
    }

    return TEE_SUCCESS;
}

TEE_Result generate_key(unsigned long obj,
                        unsigned long key_size,
                        const struct utee_attribute* usr_params,
                        unsigned long param_count) {
    TEE_Result result = TEE_SUCCESS;
    void* session = NULL;
    struct utee_attribute* attr_list = NULL;

    session = TEE_GetCurrentSession();
    if (!session) {
        return TEE_ERROR_GENERIC;
    }

    result = TEE_CheckObjectState(obj, session);
    if (result != TEE_SUCCESS) {
        return result;
    }

    attr_list = calloc(param_count, sizeof(struct utee_attribute));
    if (!attr_list) {
        return TEE_ERROR_OUT_OF_MEMORY;
    }

    memcpy(attr_list, usr_params, param_count * sizeof(struct utee_attribute));

    if (key_size < MIN_KEY_SIZE || key_size > MAX_KEY_SIZE) {
        result = TEE_ERROR_BAD_PARAMETERS;
        goto cleanup;
    }

    if (is_rsa_object(obj)) {
        result = TEE_GenerateRSAKey(obj, key_size, attr_list, param_count);
    } else if (is_aes_object(obj)) {
        result = TEE_GenerateAESKey(obj, key_size, attr_list, param_count);
    } else if (is_dsa_object(obj)) {
        result = TEE_GenerateDSAKey(obj, key_size, attr_list, param_count);
    } else {
        result = TEE_ERROR_NOT_SUPPORTED;
    }

cleanup:
    if (attr_list) {
        free(attr_list);
    }

    return result;
}

TEE_Result generate_key_for_object(unsigned long obj,
                                   unsigned long key_size,
                                   const struct utee_attribute *usr_params,
                                   unsigned long param_count) {
    TEE_Result result = TEE_SUCCESS;
    void *session = TEE_GetCurrentSession();
    struct object_state *obj_state = get_object_state(obj);

    if (!obj_state) {
        return TEE_ERROR_ITEM_NOT_FOUND;
    }

    if (key_size < obj_state->min_key_size || key_size > obj_state->max_key_size) {
        return TEE_ERROR_BAD_PARAMETERS;
    }

    struct utee_attribute *attributes =
        (struct utee_attribute *)malloc(param_count * sizeof(struct utee_attribute));
    if (!attributes) {
        return TEE_ERROR_OUT_OF_MEMORY;
    }

    for (unsigned long i = 0; i < param_count; ++i) {
        attributes[i] = usr_params[i];
    }

    if (obj_state->type == OBJ_TYPE_AES) {
        result = generate_aes_key(obj, key_size, attributes, param_count);
    } else if (obj_state->type == OBJ_TYPE_RSA) {
        result = generate_rsa_key(obj, key_size, attributes, param_count);
    } else if (obj_state->type == OBJ_TYPE_DSA) {
        result = generate_dsa_key(obj, key_size, attributes, param_count);
    } else {
        result = TEE_ERROR_NOT_SUPPORTED;
    }

    free(attributes);

    if (result != TEE_SUCCESS) {
        obj_state->error_count++;
    }

    return result;
}

TEE_Result generate_crypto_key(
    unsigned long obj,
    unsigned long key_size,
    const struct utee_attribute* usr_params,
    unsigned long param_count)
{
    TEE_Result result = TEE_SUCCESS;
    void* session = NULL;
    struct utee_attribute* attributes = NULL;
    unsigned long attr_size = 0;

    session = get_current_session();
    if (!session) {
        return TEE_ERROR_BAD_STATE;
    }

    if (!is_object_valid(obj)) {
        return TEE_ERROR_BAD_PARAMETERS;
    }

    attr_size = sizeof(struct utee_attribute) * param_count;
    attributes = malloc(attr_size);
    if (!attributes) {
        return TEE_ERROR_OUT_OF_MEMORY;
    }

    memcpy(attributes, usr_params, attr_size);

    if (key_size < MIN_KEY_SIZE || key_size > MAX_KEY_SIZE) {
        free(attributes);
        return TEE_ERROR_BAD_PARAMETERS;
    }

    result = generate_key_for_object(obj, key_size, attributes, param_count);
    if (result != TEE_SUCCESS) {
        free(attributes);
        return result;
    }

    free(attributes);
    return TEE_SUCCESS;
}

TEE_Result generate_key(unsigned long obj,
                        unsigned long key_size,
                        const struct utee_attribute *usr_params,
                        unsigned long param_count) {
    TEE_Result result = TEE_ERROR_GENERIC;
    void *session = NULL;
    struct key_attributes *attributes = NULL;

    session = get_current_session();
    if (!session) {
        return TEE_ERROR_BAD_STATE;
    }

    result = validate_object_state(obj, session);
    if (result != TEE_SUCCESS) {
        return result;
    }

    attributes = allocate_key_attributes(param_count);
    if (!attributes) {
        return TEE_ERROR_OUT_OF_MEMORY;
    }

    result = validate_key_size(key_size);
    if (result != TEE_SUCCESS) {
        goto cleanup;
    }

    result = apply_user_attributes(usr_params, param_count, attributes);
    if (result != TEE_SUCCESS) {
        goto cleanup;
    }

    switch (get_object_type(obj)) {
        case OBJECT_TYPE_AES:
            result = generate_aes_key(obj, key_size, attributes);
            break;
        case OBJECT_TYPE_RSA:
            result = generate_rsa_key(obj, key_size, attributes);
            break;
        case OBJECT_TYPE_DSA:
            result = generate_dsa_key(obj, key_size, attributes);
            break;
        default:
            result = TEE_ERROR_NOT_SUPPORTED;
            break;
    }

cleanup:
    free_key_attributes(attributes);
    return result;
}
